context.prefix:
'use client'
import { useRouter, useSearchParams } from 'next/navigation'

interface PaginationProps {
  currentPage: number
  totalPages: number
  baseHref: string
}

export default function Pagination({ currentPage, totalPages, baseHref }: PaginationProps) {

output:
  const router = useRouter()
  const searchParams = useSearchParams()

  const handlePageChange = (page: number) => {
    const newPage = page + 1
    const newSearch = new URLSearchParams(searchParams.toString())
    newSearch.set('page', newPage.toString())
    router.push(`${baseHref}?${newSearch.toString()}`)
  }

  return (
    <nav>
      <ul>
        {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
          <li key={page}>
            <button onClick={() => handlePageChange(page - 1)}>Previous</button>
            <button onClick={() => handlePageChange(page)}>Page {page}</button>
            <button onClick={() => handlePageChange(page + 1)}>Next</button>
          </li>
        ))}
      </ul>
    </nav>
  )
}

