// app/posts/page.tsx
import { prisma } from '@/lib/prisma'

interface PageProps {
  searchParams: { q?: string; page?: string; sort?: string }
}

export default async function PostsPage({ searchParams }: PageProps) {

output:
  const { q: query, page, sort } = searchParams

  const pageQuery = page ? parseInt(page, 10) : 1
  const sortQuery = sort ? sort : 'desc'

  const posts = await prisma.post.findMany({
    where: {
      OR: [
        {
          title: {
            contains: query || '',
          },
        },
        {
          content: {
            contains: query || '',
          },
        },
      ],
    },
    orderBy: {
      createdAt: sortQuery,
    },
    skip: (pageQuery - 1) * 10,
    take: 10,
  })

  const totalPosts = await prisma.post.count({
    where: {
      OR: [
        {
          title: {
            contains: query || '',
          },
        },
        {
          content: {
            contains: query || '',
          },
        },
      ],
    },
  })

  const totalPages = Math.ceil(totalPosts / 10)

  return {
    props: {
      posts,
      totalPages,
      pageQuery,
      totalPages,
      sortQuery,
    },
  }
}

