// app/deals/page.tsx
import { prisma } from '@/lib/prisma'

interface PageProps {
  searchParams: { q?: string; page?: string; sort?: string }
}

export default async function DealsPage({ searchParams }: PageProps) {

output:
  const { q: query, page, sort } = searchParams

  const pageQuery = page ? parseInt(page, 10) : 1
  const sortQuery = sort ? sort : 'createdAt'

  const deals = await prisma.deal.findMany({
    where: {
      OR: [
        {
          name: {
            contains: query,
            mode: 'insensitive',
          },
        },
        {
          description: {
            contains: query,
            mode: 'insensitive',
          },
        },
      ],
    },
    orderBy: {
      [sortQuery]: 'desc',
    },
    skip: (pageQuery - 1) * 10,
    take: 10,
  })

  const totalDeals = await prisma.deal.count({
    where: {
      OR: [
        {
          name: {
            contains: query,
            mode: 'insensitive',
          },
        },
        {
          description: {
            contains: query,
            mode: 'insensitive',
          },
        },
      ],
    },
  })

  const totalPages = Math.ceil(totalDeals / 10)

  return {
    props: {
      deals,
      totalPages,
      pageQuery,
      sortQuery,
      totalPages,
      query,
    },
  }
}

