const Schema = z.object({ id: z.string().cuid() })

export async function archiveOrderWithChildren(input: unknown) {

output:
  const { id } = Schema.parse(input)

  const order = await prisma.order.findUnique({
    where: { id },
    include: {
      customer: true,
      items: {
        include: {
          product: true,
        },
      },
    },
  })

  if (!order) {
    throw new Error('Order not found')
  }

  const archivedOrder = await prisma.order.update({
    where: { id },
    data: {
      archived: true,
    },
  })

  await prisma.customer.update({
    where: { id: archivedOrder.customerId },
    data: {
      archived: true,
    },
  })

  await prisma.product.updateMany({
    where: { id: { in: archivedOrder.items.map((item) => item.productId) } },
    data: {
      archived: true,
    },
  })

  revalidatePath('/orders')
  revalidatePath(`/orders/${archivedOrder.id}`)
}

