context.prefix:
// app/actions/workspace/archive-cascade.ts
'use server'
import { z } from 'zod'
import { prisma } from '@/lib/prisma'
import { revalidatePath } from 'next/cache'

const Schema = z.object({ id: z.string().cuid() })

export async function archiveWorkspaceWithChildren(input: unknown) {

output:
  const { id } = Schema.parse(input)

  const cascade = prisma.cascade.findUniqueOrThrow({
    where: { id },
    include: {
      cascade: {
        include: {
          cascade: true,
        },
      },
    },
  })

  const cascadeWithChildren = await prisma.$transaction(async (tx) => {
    const cascade = await tx.cascade.findUniqueOrThrow({
      where: { id },
      include: {
        cascade: true,
      },
    })

    const cascadeWithChildren = await tx.cascade.update({
      where: { id },
      data: {
        archived: true,
        cascade: {
          create: cascade.cascade.map((cascade) => ({
            archived: true,
            cascade: {
              create: cascade.cascade.map((cascade) => ({
                archived: true,
                cascade: {
                  create: cascade.cascade,
                },
              })),
            },
          })),
        },
      },
      include: {
        cascade: true,
      },
    })

    return cascadeWithChildren
  })

  revalidatePath('/workspace', 'page')
  revalidatePath(`/workspace/${cascadeWithChildren.cascade.id}`, 'page')
  revalidatePath(`/workspace/${cascadeWithChildren.cascade.id}/cascade`, 'page')
  revalidatePath(`/workspace/${cascadeWithChildren.cascade.id}/cascade/cascade`, 'page')
}

