// app/api/webhooks/stripe/route.ts
import { NextResponse } from 'next/server'

export async function POST(req: Request) {
  const body = await req.text()
  const signature = req.headers.get('stripe-signature')

output:
  if (!signature) {
    return NextResponse.json({ message: 'Signature not found' }, { status: 400 })
  }

  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET
  if (!webhookSecret) {
    return NextResponse.json({ message: 'Webhook secret not found' }, { status: 500 })
  }

  let event

  try {
    event = stripe.webhooks.constructEvent(body, signature, webhookSecret)
  } catch (err) {
    return NextResponse.json({ message: 'Webhook signature verification failed' }, { status: 400 })
  }

  switch (event.type) {
    case 'checkout.session.completed':
      const checkoutSession = event.data.object as Stripe.Checkout.Session
      break
    case 'payment_intent.succeeded':
      const paymentIntent = event.data.object as Stripe.PaymentIntent
      break
    case 'customer.subscription.created':
      const subscription = event.data.object as Stripe.Subscription
      break
    case 'customer.subscription.updated':
      const updatedSubscription = event.data.object as Stripe.Subscription
      break
    case 'customer.subscription.deleted':
      const deletedSubscription = event.data.object as Stripe.Subscription
      break
    default:
      console.log(`Unhandled event type ${event.type}`)
      break
  }

  return NextResponse.json({ message: 'Webhook received' }, { status: 200 })
}

