      body: JSON.stringify({ name, email, message }),
    })

    if (response.ok) {
      alert('Form submitted successfully!')
      setName('')
      setEmail('')
      setMessage('')
    } else {
      alert('Error submitting form.')
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="name">Name:</label>
        <input
          type="text"
          id="name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
      </div>
