// InvoiceService interface — create, read, update, delete
export interface InvoiceService {
  create(invoice: Invoice): Promise<Invoice>;
  read(id: string): Promise<Invoice>;
  update(id: string, invoice: Invoice): Promise<Invoice>;
  delete(id: string): Promise<void>;
}

// InvoiceService implementation — create, read, update, delete
export class InvoiceServiceImpl implements InvoiceService {
  private invoices: Invoice[] = [];

  async create(invoice: Invoice): Promise<Invoice> {
    const newInvoice: Invoice = {
      ...invoice,
      createdAt: new Date(),
    };
    this.invoices.push(newInvoice);
    return newInvoice;
  }

  async read(id: string): Promise<Invoice> {
    const invoice = this.invoices.find((invoice) => invoice.id === id);
    if (!invoice) {
      throw new Error(`Invoice with id ${id} not found`);
    }
    return invoice;
  }

  async update(id: string, invoice: Invoice): Promise<Invoice> {
    const index = this.invoices.findIndex((invoice) => invoice.id === id);
    if (index === -1) {
      throw new Error(`Invoice with id ${id} not found`);
    }
    const updatedInvoice: Invoice = {
      ...invoice,
      id,
      createdAt: this.invoices[index].createdAt,
    };
    this.invoices[index] = updatedInvoice;
    return updatedInvoice;
  }

  async delete(id: string): Promise<void> {
    const index = this.invoices.findIndex((invoice) => invoice.id === id);
    if (index === -1) {
      throw new Error(`Invoice with id ${id} not found`);
    }
    this.invoices.splice(index, 1);
  }
}

