              key={rowKey(row)}
              onClick={() => handleRowClick(row)}
              className={selectedRow === row ? 'selected' : ''}
            >
              {columns.map((column) => (
                <td key={column.key}>{column.render ? column.render(row[column.key], row) : row[column.key]}</td>
