output:
  const [isOpen, setIsOpen] = useState(false)
  const menuRef = useRef(null)

  const handleClickOutside = (event: MouseEvent) => {
    if (menuRef.current && !menuRef.current.contains(event.target)) {
      setIsOpen(false)
    }
