      <button
        className="bg-gray-200 px-4 py-2 rounded-md"
        onClick={handleToggle}
      >
        {trigger}
      </button>
      {isOpen && (
        <div className="absolute z-10 bg-white shadow-lg rounded-md" ref={menuRef}>
          <ul>
            {items.map((item) => (
