export async function PATCH(req: Request, { params }: { params: { id: string } }) {

output:
  const { id } = params
  const { title, body } = await Schema.parse(await req.json())

  const post = await prisma.post.update({
    where: { id },
    data: { title, body },
  })

  return NextResponse.json(post)
}

